<?php
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
// Uses connection-local temporary copies. No customer data is modified.
require_once __DIR__ . '/../include/payment_ledger.php';
$db = new PDO('mysql:host=localhost;dbname=aitf_web;charset=utf8mb4', 'root', '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$fixtureInvoice = $db->query('SELECT * FROM invoice_details WHERE invoice_id=1760 AND customer_id=380')->fetch(PDO::FETCH_ASSOC);
foreach (['customer_info','payment_system_id','payment_system','payment_block_comments','invoice_details','service'] as $table) {
    $ddl = $db->query("SHOW CREATE TABLE `$table`")->fetch(PDO::FETCH_NUM)[1];
    $db->exec(preg_replace('/^CREATE TABLE/', 'CREATE TEMPORARY TABLE', $ddl));
}
$db->exec('INSERT INTO customer_info (id) VALUES (380),(381)');
aitf_payment_schema($db);
if (!$fixtureInvoice) throw new RuntimeException('Local invoice fixture is missing.');
$db->prepare('INSERT INTO invoice_details (`'.implode('`,`',array_keys($fixtureInvoice)).'`) VALUES ('.implode(',',array_fill(0,count($fixtureInvoice),'?')).')')->execute(array_values($fixtureInvoice));
$checks = 0;
function check($condition, $message) { global $checks; if (!$condition) throw new RuntimeException($message); ++$checks; }
function rejected(callable $fn, $message) { try { $fn(); } catch (Throwable $e) { check(true,$message); return; } throw new RuntimeException($message); }
function countRows($db) { return (int)$db->query('SELECT COUNT(*) FROM payment_system')->fetchColumn(); }
$blank = ['key'=>'blank_row_123', 'header'=>'SA-II', 'received'=>'0', 'discount'=>'0','date'=>''];
$result = aitf_payment_save($db,380,[$blank]);
check(countRows($db)===0 && !$result['payid'], 'Zero-only row must not create payment or ledger');
$row = ['key'=>'receipt_row_123', 'header'=>'Till Sep 2026', 'received'=>'23600', 'tds'=>'0', 'date'=>'16.01.2026','instrument'=>'000769'];
$result = aitf_payment_save($db,380,[$row]);
$id = $result['rows'][0]['id'];
check(countRows($db)===1 && $id>0, 'Valid receipt saved');
check((int)$db->query('SELECT customer_id FROM payment_system_id')->fetchColumn()===380,'Ledger belongs to customer');
$retry = aitf_payment_save($db,380,[$row]);
check(countRows($db)===1 && $retry['rows'][0]['id']===$id && $retry['rows'][0]['replayed'], 'Lost-response retry must reuse receipt');
$row['id']=$id; $row['version']=0;
$db->prepare('UPDATE payment_system SET comment=? WHERE payment_id=?')->execute(['Preserve this note',$id]);
$row['instrument']='updated instrument';
$result = aitf_payment_save($db,380,[$row]);
check($result['rows'][0]['version']===1, 'Version advances');
check($db->query('SELECT comment FROM payment_system')->fetchColumn()==='Preserve this note','Instrument edit must not overwrite notes');
rejected(function() use($db,$row) { aitf_payment_save($db,380,[$row]); }, 'Reject stale tab');
$row['version']=1;
rejected(function() use($db,$row) { aitf_payment_save($db,381,[$row]); }, 'Reject cross-customer row');
$bad=$blank; $bad['received']='10'; $bad['date']='31.02.2026';
rejected(function() use($db,$row,$bad) { $row['received']='99'; aitf_payment_save($db,380,[$row,$bad]); }, 'Reject invalid dates atomically');
check((float)$db->query('SELECT payment_received FROM payment_system')->fetchColumn()===23600.0,'Entire batch rolls back');
$bad['date']='01.10.2026'; $bad['received']='-5';
rejected(function() use($db,$bad) { aitf_payment_save($db,380,[$bad]); },'Reject negative amounts');
$db->exec("UPDATE payment_system SET reconciliation='Verified'");
rejected(function() use($db,$row) { aitf_payment_save($db,380,[$row]); }, 'Cannot edit verified receipt');
rejected(function() use($db,$id) { aitf_payment_delete($db,380,$id,1); }, 'Cannot delete verified receipt');
$db->exec("UPDATE payment_system SET reconciliation='Verify',tds_verified='verified'");
rejected(function() use($db,$id) { aitf_payment_delete($db,380,$id,1); }, 'Cannot delete TDS-verified receipt');
$db->exec("UPDATE payment_system SET tds_verified='unverified'");
rejected(function() use($db,$id) { aitf_payment_delete($db,380,$id,0); }, 'Stale delete rejected');
aitf_payment_delete($db,380,$id,1);
check(countRows($db)===0,'Delete removes only requested receipt');
rejected(function() use($db,$row) { aitf_payment_save($db,380,[$row]); }, 'Stale save must not resurrect deleted receipt');
check(aitf_payment_meaningful(['payment_received'=>0,'payment_date'=>'2026-10-09']), 'Preserve date-only entry');
check(aitf_payment_meaningful(['payment_received'=>0,'tds_amount'=>100]),'Preserve TDS-only rows');
check(aitf_payment_meaningful(['payment_received'=>0,'comment'=>'Adjustment pending']),'Preserve real notes');
$legacy=['service_type'=>'RC','payment_date'=>'2024-04-19','payment_received'=>29500];
check(aitf_payment_header($legacy,true)==='Till Sep 2026','Legacy receipt stays in historical header');
$legacy['payment_header']='SA-II';
check(aitf_payment_header($legacy,true)==='SA-II','Explicit grouping survives date changes');
$tds = ['key'=>'tds_only_row_123','header'=>'SA-II','received'=>0,'tds'=>500];
$result=aitf_payment_save($db,380,[$tds]);
check((float)$db->query('SELECT payment_received FROM payment_system')->fetchColumn()===0.0,'TDS-only receipt is not duplicated as cash');
check((float)$db->query('SELECT tds_amount FROM payment_system')->fetchColumn()===500.0,'TDS value preserved');
rejected(function() use($db) { aitf_payment_move_invoice($db,99999999,'SA-II',380); }, 'Missing invoice cannot report success');
$before = $db->query('SELECT * FROM payment_system')->fetchAll(PDO::FETCH_ASSOC);
aitf_payment_move_invoice($db,1760,'New cycle',380);
check($db->query('SELECT service_type FROM invoice_details WHERE invoice_id=1760')->fetchColumn()==='New cycle','Move invoice preserves explicit header');
check($db->query('SELECT * FROM payment_system')->fetchAll(PDO::FETCH_ASSOC)===$before,'Invoice move must not reclassify unrelated receipts');
rejected(function()use($db){aitf_payment_move_invoice($db,1760,'Wrong owner',381);},'Invoice move validates customer');
aitf_payment_change_header($db,380,'createPaymentHeader',['service_type'=>'Empty new header']);
check((int)$db->query("SELECT is_explicit FROM payment_block_comments WHERE service_type='Empty new header'")->fetchColumn()===1,'Empty headers persist without payments');
check(countRows($db)===1,'Header create cannot create zero receipt');
$pid=$result['rows'][0]['id'];
$request=['service_type'=>'Renamed cycle','source_service'=>'New cycle','invoice_ids'=>'[1760]','payment_ids'=>json_encode([$pid]),'payment_versions'=>json_encode([$pid=>99])];
rejected(function()use($db,$request){aitf_payment_change_header($db,380,'renamePaymentHeader',$request);},'Rename rejects stale receipt');
check($db->query('SELECT service_type FROM invoice_details WHERE invoice_id=1760')->fetchColumn()==='New cycle','Failed rename leaves invoice unchanged');
$db->prepare('UPDATE payment_system SET payment_header=? WHERE payment_id=?')->execute(['New cycle',$pid]);
$request['payment_versions']=json_encode([$pid=>0]);
$db->prepare('UPDATE payment_block_comments SET comment=? WHERE service_type=?')->execute(['Keep notes','New cycle']);
aitf_payment_change_header($db,380,'renamePaymentHeader',$request);
check($db->query('SELECT payment_header FROM payment_system')->fetchColumn()==='Renamed cycle','Rename moves saved receipts');
check($db->query('SELECT service_type FROM invoice_details WHERE invoice_id=1760')->fetchColumn()==='Renamed cycle','Rename moves invoices');
check($db->query("SELECT comment FROM payment_block_comments WHERE service_type='Renamed cycle'")->fetchColumn()==='Keep notes','Rename preserves notes');
rejected(function()use($db){aitf_payment_change_header($db,380,'removePaymentHeader',['service_type'=>'Renamed cycle']);},'Cannot remove populated header');
aitf_payment_change_header($db,380,'removePaymentHeader',['service_type'=>'Empty new header']);
check((int)$db->query("SELECT COUNT(*) FROM payment_block_comments WHERE service_type='Empty new header'")->fetchColumn()===0,'Empty header removal persists');
$verified=aitf_payment_verify($db,$pid,'Verified','reconciliation');
check($verified['locked'] && $verified['version']===2,'Verification updates lock and version');
$unverified=aitf_payment_verify($db,$pid,'Verify','reconciliation');
check(!$unverified['locked'] && $unverified['version']===3,'Unverify restores editing with new version');
rejected(function()use($db,$pid){aitf_payment_verify($db,$pid,'anything','reconciliation');},'Reject invalid verification state');
// Receipts linked by the retired mapping feature must also stay untouched.
if (!$db->query("SHOW COLUMNS FROM payment_system LIKE 'linked_invoice_id'")->fetch()) $db->exec('ALTER TABLE payment_system ADD COLUMN linked_invoice_id INT NULL');
$db->prepare('UPDATE payment_system SET linked_invoice_id=1760 WHERE payment_id=?')->execute([$pid]);
$before=$db->query('SELECT * FROM payment_system ORDER BY payment_id')->fetchAll(PDO::FETCH_ASSOC);
aitf_payment_move_invoice($db,1760,'Manual receipts',380);
check($db->query('SELECT * FROM payment_system ORDER BY payment_id')->fetchAll(PDO::FETCH_ASSOC)===$before,'Invoice move leaves all receipts unchanged, including previously linked receipts');
$secondManual=aitf_payment_change_header($db,380,'createPaymentHeader',['service_type'=>'manual receipts']);
check(strcasecmp($secondManual['service_type'],'Manual receipts')!==0 && $secondManual['header_name']==='manual receipts','Repeated service creates a distinct header');
check($db->query('SELECT * FROM payment_system ORDER BY payment_id')->fetchAll(PDO::FETCH_ASSOC)===$before,'Header creation never inserts a receipt');
check(!aitf_payment_block_meaningful([],[],'0.00'),'Empty header with zero note is hidden');
check(!aitf_payment_block_meaningful([],[['payment_received'=>'0.00','tds_amount'=>0,'payment_date'=>null,'reconciliation'=>'Verify']],' '),'Zero-only unverified rows do not keep a header');
check(aitf_payment_block_meaningful([],[['payment_received'=>1]],''),'One-rupee receipt keeps its header');
check(aitf_payment_block_meaningful([],[['cheque_details'=>'NEFT']],''),'Instrument-only row keeps its header');
check(aitf_payment_block_meaningful([],[['payment_date'=>'2026-10-01']],''),'Date-only row keeps its header');
check(aitf_payment_block_meaningful([],[],'Pending receipt'),'Notes-only header remains');
check(aitf_payment_block_meaningful([['invoice_id'=>1760,'final_amount'=>0]],[],''),'Real zero-value invoice remains');
check(aitf_payment_block_meaningful([],[['reconciliation'=>'Verified'] ],''),'Verified records remain protected');
$draft=['key'=>'partial_date_entry','header'=>'Date only','date'=>'01.10.2026'];
$savedDraft=aitf_payment_save($db,380,[$draft]);
check($savedDraft['rows'][0]['id']>0,'Save a date before entering its amount');
$draft=['key'=>'partial_instrument_entry','header'=>'Instrument only','instrument'=>'NEFT'];
$savedDraft=aitf_payment_save($db,380,[$draft]);
check($savedDraft['rows'][0]['id']>0,'Save an instrument before entering its amount');
// Same service can recur in separate cycles, with retry-safe creation and stable order.
$before = $db->query('SELECT * FROM payment_system ORDER BY payment_id')->fetchAll(PDO::FETCH_ASSOC);
$cycle = [];
foreach (['CA','SA-I','RC','CA'] as $i=>$label) {
    $cycle[] = aitf_payment_change_header($db,380,'createPaymentHeader',['service_type'=>$label,'creation_key'=>'cycle_header_key_'.$i]);
}
$keys = array_column($cycle,'service_type');
check(count(array_unique($keys))===4,'Repeated CA has an independent storage key');
check(array_column($cycle,'header_name')===['CA','SA-I','RC','CA'],'Repeated CA keeps its display label');
$catalog = aitf_payment_header_catalog($db,380);
check(aitf_payment_sort_headers(array_reverse($keys),$catalog)===$keys,'Reload sorts repeated cycles by creation order');
$retry = aitf_payment_change_header($db,380,'createPaymentHeader',['service_type'=>'CA','creation_key'=>'cycle_header_key_3']);
check($retry['service_type']===$keys[3] && $retry['replayed'],'Lost response retry does not create another CA');
$next = aitf_payment_change_header($db,380,'createPaymentHeader',['service_type'=>'ca','creation_key'=>'cycle_header_key_4']);
check(!in_array(strtoupper($next['service_type']),array_map('strtoupper',$keys),true),'Case variants also get independent keys');
check($db->query('SELECT * FROM payment_system ORDER BY payment_id')->fetchAll(PDO::FETCH_ASSOC)===$before,'Repeated header creation leaves receipts untouched');
foreach ([$keys[0]=>'First CA note',$keys[3]=>'Second CA note'] as $key=>$note) $db->prepare('UPDATE payment_block_comments SET comment=? WHERE customer_id=380 AND service_type=?')->execute([$note,$key]);
aitf_payment_move_invoice($db,1760,$keys[3],380);
check($db->query('SELECT service_type FROM invoice_details WHERE invoice_id=1760')->fetchColumn()===$keys[3],'Invoice moves to selected repeated CA only');
check($db->query('SELECT * FROM payment_system ORDER BY payment_id')->fetchAll(PDO::FETCH_ASSOC)===$before,'Invoice move to repeated CA does not move receipts');
$moved = aitf_payment_move_receipt($db,380,$pid,$keys[3],3);
$q = $db->prepare('SELECT payment_header FROM payment_system WHERE payment_id=?'); $q->execute([$pid]);
check($q->fetchColumn()===$keys[3],'Manual receipt move uses repeated header key');
$renamed = aitf_payment_change_header($db,380,'renamePaymentHeader',['source_service'=>$keys[3],'service_type'=>'RC','invoice_ids'=>'[1760]','payment_ids'=>json_encode([$pid]),'payment_versions'=>json_encode([$pid=>$moved['version']])]);
check($renamed['service_type']!==$keys[2] && $renamed['header_name']==='RC','Rename to existing label keeps separate headers');
$afterCatalog=aitf_payment_header_catalog($db,380);
check($afterCatalog[strtoupper($renamed['service_type'])]['header_order']===$catalog[strtoupper($keys[3])]['header_order'],'Rename preserves header position');
check($afterCatalog[strtoupper($keys[0])]['comment']==='First CA note' && $afterCatalog[strtoupper($renamed['service_type'])]['comment']==='Second CA note','Namesake notes remain separate after rename');
$q->execute([$pid]);check($q->fetchColumn()===$renamed['service_type'],'Rename updates only selected receipt header');
check($db->query('SELECT service_type FROM invoice_details WHERE invoice_id=1760')->fetchColumn()===$renamed['service_type'],'Rename updates selected invoice header');
$other = aitf_payment_change_header($db,381,'createPaymentHeader',['service_type'=>'CA','creation_key'=>'cycle_header_key_3']);
check($other['service_type']==='CA','Header retry keys and names are scoped to customer');
rejected(function()use($db,$keys){aitf_payment_change_header($db,380,'renamePaymentHeader',['source_service'=>$keys[0],'service_type'=>'RC','invoice_ids'=>'[1760]']);},'Rename cannot steal another repeated header invoice');
// Exercise the account page's real grouping on a fresh read, without its mail/header side effects.
$db->prepare('UPDATE payment_block_comments SET comment=? WHERE customer_id=380 AND service_type=?')->execute(['Original RC note',$keys[2]]);
$_GET['customerid']=380;
$invoiceList=$db->query('SELECT * FROM invoice_details WHERE customer_id=380')->fetchAll(PDO::FETCH_ASSOC);
$paymentInfo=$db->query('SELECT * FROM payment_system WHERE customer_id=380')->fetchAll(PDO::FETCH_ASSOC);
$source=file_get_contents(__DIR__.'/../customerAccount.php');
$start=strpos($source,"// Payment service grouping starts here.");
$end=strpos($source,'?>',$start);
eval(substr($source,$start,$end-$start));
check(in_array($keys[2],$activeServiceBlocks,true) && in_array($renamed['service_type'],$activeServiceBlocks,true),'Actual account grouping preserves both RC headers after reload');
check(count($invoicesByService[$renamed['service_type']])===1 && empty($invoicesByService[$keys[2]]),'Reload keeps invoice in selected RC header');
check(count($paymentsByService[$renamed['service_type']])===1 && empty($paymentsByService[$keys[2]]),'Reload keeps receipt in selected RC header');
check(array_search($keys[2],$activeServiceBlocks,true)<array_search($renamed['service_type'],$activeServiceBlocks,true),'Reload keeps repeated RC after the original RC');
echo "PASS: $checks payment ledger checks (temporary tables only).\n";
